changeSet.sql:
CREATE EXTENSION IF NOT EXISTS pgcrypto;

DO $$
DECLARE
    constraint_record RECORD;
    column_record RECORD;
BEGIN
    -- Remove dependent foreign keys while the numeric columns are converted.
    FOR constraint_record IN
        SELECT conrelid::regclass AS table_name, conname
        FROM pg_constraint
        WHERE contype = 'f'
          AND (conrelid::regclass::text IN ('house', 'house_image', 'room', 'room_image', 'rent_requests', 'password_reset_token')
               OR confrelid::regclass::text IN ('house', 'house_image', 'room', 'room_image', 'rent_requests', 'password_reset_token'))
    LOOP
        EXECUTE format('ALTER TABLE %s DROP CONSTRAINT %I', constraint_record.table_name, constraint_record.conname);
    END LOOP;

    -- Replace identity-backed primary keys instead of altering their type.
    FOR column_record IN
                        SELECT table_name, column_name
        FROM information_schema.columns
        WHERE table_schema = current_schema()
                            AND ((table_name IN ('house_image', 'room_image', 'rent_requests', 'password_reset_token')
                                        AND column_name = 'id')
                                     OR (table_name = 'house' AND column_name = 'house_id'))
          AND data_type IN ('bigint', 'integer')
    LOOP
        EXECUTE format('ALTER TABLE %I ADD COLUMN id_uuid UUID', column_record.table_name);
                        EXECUTE format('UPDATE %I SET id_uuid = md5(%I::text)::uuid', column_record.table_name, column_record.column_name);
        EXECUTE format('ALTER TABLE %I ALTER COLUMN id_uuid SET NOT NULL', column_record.table_name);
                        EXECUTE format('ALTER TABLE %I DROP COLUMN %I', column_record.table_name, column_record.column_name);
                        EXECUTE format('ALTER TABLE %I RENAME COLUMN id_uuid TO %I', column_record.table_name, column_record.column_name);
    END LOOP;

    -- The conversion is deterministic, so old references remain equivalent.
    FOR column_record IN
        SELECT table_name, column_name
        FROM information_schema.columns
        WHERE table_schema = current_schema()
          AND data_type IN ('bigint', 'integer')
          AND ((table_name IN ('house', 'house_image', 'room', 'room_image', 'rent_requests', 'password_reset_token')
                AND column_name IN ('id', 'house_id', 'room_id'))
               OR column_name IN ('house_id', 'room_id'))
          AND table_name <> 'users'
           AND column_name <> 'id'
    LOOP
        IF column_record.column_name = 'id' THEN
            EXECUTE format(
                'ALTER TABLE %I ALTER COLUMN %I DROP IDENTITY IF EXISTS',
                column_record.table_name, column_record.column_name);
        END IF;
        EXECUTE format(
            'ALTER TABLE %I ALTER COLUMN %I TYPE UUID USING md5(%I::text)::uuid',
            column_record.table_name, column_record.column_name, column_record.column_name);
    END LOOP;
END $$;

ALTER TABLE house ADD CONSTRAINT house_pkey PRIMARY KEY (house_id);
ALTER TABLE house_image ADD CONSTRAINT house_image_pkey PRIMARY KEY (id);
ALTER TABLE room_image ADD CONSTRAINT room_image_pkey PRIMARY KEY (id);
ALTER TABLE rent_requests ADD CONSTRAINT rent_requests_pkey PRIMARY KEY (id);
ALTER TABLE password_reset_token ADD CONSTRAINT password_reset_token_pkey PRIMARY KEY (id);

ALTER TABLE house
    ADD CONSTRAINT fk_house_host FOREIGN KEY (host_id) REFERENCES users(id),
    ADD CONSTRAINT fk_house_agent FOREIGN KEY (agent_id) REFERENCES users(id);
ALTER TABLE house_image
    ADD CONSTRAINT fk_house_image_house FOREIGN KEY (house_id) REFERENCES house(house_id);
ALTER TABLE room
    ADD CONSTRAINT fk_room_house FOREIGN KEY (house_id) REFERENCES house(house_id),
    ADD CONSTRAINT fk_room_client FOREIGN KEY (client_id) REFERENCES users(id);
ALTER TABLE room_image
    ADD CONSTRAINT fk_room_image_room FOREIGN KEY (room_id) REFERENCES room(room_id);
ALTER TABLE rent_requests
    ADD CONSTRAINT fk_rent_request_client FOREIGN KEY (client_id) REFERENCES users(id),
    ADD CONSTRAINT fk_rent_request_owner FOREIGN KEY (house_owner_id) REFERENCES users(id),
    ADD CONSTRAINT fk_rent_request_agent FOREIGN KEY (agent_id) REFERENCES users(id),
    ADD CONSTRAINT fk_rent_request_room FOREIGN KEY (room_id) REFERENCES room(room_id);

DO $$
DECLARE
    constraint_record RECORD;
    column_record RECORD;
    primary_key_name TEXT;
BEGIN
    -- Capture all real user foreign keys before dropping them. This covers every
    -- relationship column regardless of its application-level field name.
    CREATE TEMP TABLE user_fk_definitions (
        table_name TEXT NOT NULL,
        constraint_name TEXT NOT NULL,
        constraint_definition TEXT NOT NULL
    ) ON COMMIT DROP;
    CREATE TEMP TABLE user_fk_columns (
        table_name TEXT NOT NULL,
        column_name TEXT NOT NULL
    ) ON COMMIT DROP;

    INSERT INTO user_fk_definitions (table_name, constraint_name, constraint_definition)
    SELECT conrelid::regclass::text, conname, pg_get_constraintdef(oid)
    FROM pg_constraint
    WHERE contype = 'f' AND confrelid = 'users'::regclass;

    INSERT INTO user_fk_columns (table_name, column_name)
    SELECT c.conrelid::regclass::text, a.attname
    FROM pg_constraint c
    CROSS JOIN LATERAL unnest(c.conkey) AS key_column(attnum)
    JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = key_column.attnum
    WHERE c.contype = 'f' AND c.confrelid = 'users'::regclass;

    FOR constraint_record IN
        SELECT table_name, constraint_name FROM user_fk_definitions
    LOOP
        EXECUTE format('ALTER TABLE %s DROP CONSTRAINT %I',
            constraint_record.table_name, constraint_record.constraint_name);
    END LOOP;

    -- The UUID is deterministic for an old numeric ID, so each child reference
    -- receives exactly the UUID of the user it already points to.
    IF EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = current_schema()
          AND table_name = 'users' AND column_name = 'id'
          AND data_type IN ('smallint', 'integer', 'bigint')
    ) THEN
        SELECT conname INTO primary_key_name
        FROM pg_constraint
        WHERE contype = 'p' AND conrelid = 'users'::regclass;

        IF primary_key_name IS NOT NULL THEN
            EXECUTE format('ALTER TABLE users DROP CONSTRAINT %I', primary_key_name);
        END IF;
        ALTER TABLE users ALTER COLUMN id DROP IDENTITY IF EXISTS;
        ALTER TABLE users ALTER COLUMN id TYPE UUID USING md5(id::text)::uuid;

        FOR column_record IN
            SELECT table_name, column_name FROM user_fk_columns
        LOOP
            EXECUTE format(
                'ALTER TABLE %s ALTER COLUMN %I TYPE UUID USING md5(%I::text)::uuid',
                column_record.table_name, column_record.column_name, column_record.column_name);
        END LOOP;

        ALTER TABLE users ADD CONSTRAINT users_pkey PRIMARY KEY (id);
    END IF;

    FOR constraint_record IN
        SELECT table_name, constraint_name, constraint_definition FROM user_fk_definitions
    LOOP
        EXECUTE format('ALTER TABLE %s ADD CONSTRAINT %I %s',
            constraint_record.table_name, constraint_record.constraint_name,
            constraint_record.constraint_definition);
    END LOOP;
END $$;
